import{_ as a,o as t,c as s,ag as i}from"./chunks/framework.BwSLX4ak.js";const u=JSON.parse('{"title":"PlaceholderAPI variables","description":"","frontmatter":{},"headers":[],"relativePath":"en/shitbot/placeholders.md","filePath":"en/shitbot/placeholders.md"}'),o={name:"en/shitbot/placeholders.md"};function n(r,e,l,d,h,p){return t(),s("div",null,[...e[0]||(e[0]=[i(`<h1 id="placeholderapi-variables" tabindex="-1">PlaceholderAPI variables <a class="header-anchor" href="#placeholderapi-variables" aria-label="Permalink to &quot;PlaceholderAPI variables&quot;">​</a></h1><p>ShitBot uses PAPI in two ways: exposing its own status to scoreboards, menus, and other plugins, and reading other plugins&#39; placeholders in advanced image templates.</p><h2 id="display-shitbot-status-in-scoreboards-or-menus" tabindex="-1">Display ShitBot status in scoreboards or menus <a class="header-anchor" href="#display-shitbot-status-in-scoreboards-or-menus" aria-label="Permalink to &quot;Display ShitBot status in scoreboards or menus&quot;">​</a></h2><p>Install a PlaceholderAPI version compatible with your Spigot/Paper/Folia server and Java version, then start ShitBotSpigot normally. ShitBot registers its built-in expansion automatically. No separate <code>shitbot</code> expansion download or advanced renderer is required.</p><table tabindex="0"><thead><tr><th>Placeholder</th><th>Value</th></tr></thead><tbody><tr><td><code>%shitbot_version%</code></td><td>ShitBot version</td></tr><tr><td><code>%shitbot_ready%</code></td><td>Whether the runtime and database are ready: <code>true</code> / <code>false</code></td></tr><tr><td><code>%shitbot_connected%</code></td><td>Whether this instance is connected to OneBot: <code>true</code> / <code>false</code>; usually false on a backend</td></tr><tr><td><code>%shitbot_whitelisted%</code></td><td>Whether the player has a ShitBot whitelist entry, including entries without QQ</td></tr><tr><td><code>%shitbot_bound%</code></td><td>Whether the player has a QQ owner; <code>false</code> for an entry without QQ</td></tr><tr><td><code>%shitbot_qq%</code></td><td>The player&#39;s QQ ID; empty if unbound or whitelisted without QQ</td></tr></tbody></table><p>Player placeholders query exact, case-sensitive Minecraft IDs. Synchronous PAPI callbacks do not wait for the database: the first read starts an asynchronous query and returns an empty string; later reads use a cache lasting at most 5 seconds. Missing player context, an unready runtime, or a failed query also returns an empty string. The cache holds at most 512 players and switches to the new runtime after reload. These placeholders are for display; login and command authorization still use the database service APIs.</p><p><code>%shitbot_qq%</code> exposes the actual QQ ID. Use it only where you intend to display that information. It does not assign a fictitious QQ owner to a whitelist entry without QQ.</p><h2 id="use-other-plugins-placeholders-in-images" tabindex="-1">Use other plugins&#39; placeholders in images <a class="header-anchor" href="#use-other-plugins-placeholders-in-images" aria-label="Permalink to &quot;Use other plugins&#39; placeholders in images&quot;">​</a></h2><p>Explicitly declare the <code>papi</code> provider in the advanced template&#39;s <code>manifest.yml</code>:</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">providers</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">id</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">papi</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    player</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;\${context.player}&quot;</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    server</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;\${context.server}&quot;</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    placeholders</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">      display_name</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;%player_displayname%&quot;</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">      balance</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;%vault_eco_balance_formatted%&quot;</span></span></code></pre></div><p>Use <code>\${data.papi.display_name}</code> or <code>\${data.papi.balance}</code> in <code>scene.yml</code> text nodes. Install the plugins and expansions that supply those placeholders. Unresolved placeholders, missing plugins, offline players, and timeouts produce explicit errors.</p><p>BungeeCord/Velocity asks the target Spigot backend to resolve placeholders through the authenticated channel. The proxy does not load Bukkit&#39;s PlaceholderAPI. <code>server</code> is the backend name in the proxy configuration. Nukkit-MOT does not support Bukkit PAPI; use built-in ShitBot providers or custom third-party providers.</p><p>See <a href="/docs/en/shitbot/image-templates.html#placeholderapi-and-proxy-backends">Image rendering and advanced templates</a> for limits, caching, scheduling, error display, and command examples. Expansion integration follows <a href="https://wiki.placeholderapi.com/developers/creating-a-placeholderexpansion/" target="_blank" rel="noreferrer">PlaceholderAPI&#39;s internal expansion interface</a>.</p>`,13)])])}const k=a(o,[["render",n]]);export{u as __pageData,k as default};
